      lethal
        ? ('以上仅代表「' + who + '」的单方主观意图与尝试，随时可以被在场角色打断、拒绝、反制或无视；本世界没有主角免死光环，若「' + who + '」判断失误或贸然涉险，重伤乃至死亡都是自然且合理的真实结局。')
        : ('以上仅代表「' + who + '」的单方主观意图与尝试，随时可以被在场角色打断、拒绝、识破或无视，成败全由世界逻辑与客观实力裁定。'),
      NARR_USR_CLOSE
    ];
  } else {
    lines = [
      NARR_USR_OPEN,
      '上文回合「' + who + '」尝试采取的行动（仅作单方意图，可被他人打断或无视）：',
      NARR_ACT_OPEN,
      raw,
      NARR_ACT_CLOSE,
      NARR_USR_CLOSE
    ];
  }
  return lines.join('\n');
}

/* ---------------- 多协议消息读写（OpenAI / Claude / Gemini 原生） ---------------- */

function narrMsgList(body) {
  if (!body || typeof body !== 'object') return null;
  var root = (body.request && typeof body.request === 'object' && !Array.isArray(body.request)) ? body.request : body;
  if (Array.isArray(root.messages) && root.messages.length) return { arr: root.messages, proto: 'messages' };
  if (Array.isArray(root.contents) && root.contents.length) return { arr: root.contents, proto: 'contents' };
  return null;
}

function narrMsgIsUser(m, proto) {
  if (!m || typeof m !== 'object') return false;
  var r = String(m.role || '').toLowerCase();
  if (proto === 'contents') return r === 'user';
  return r === 'user';
}

function narrMsgText(m, proto) {
  if (!m || typeof m !== 'object') return '';
  if (proto === 'contents' || Array.isArray(m.parts)) {
    var ps = m.parts;
    if (!Array.isArray(ps)) return '';
    for (var i = 0; i < ps.length; i++) {
      var p = ps[i];
      if (p && typeof p.text === 'string' && !p.thought && !p.functionCall && !p.functionResponse) {
        return p.text;
      }
    }
    return '';
  }
  return String(textOfMsg(m) || '');
}

function narrSetMsgText(m, v, proto) {
  if (!m || typeof m !== 'object') return false;
  if (proto === 'contents' || Array.isArray(m.parts)) {
    var ps = m.parts;
    if (!Array.isArray(ps)) return false;
    for (var i = 0; i < ps.length; i++) {
      var p = ps[i];
      if (p && typeof p.text === 'string' && !p.thought && !p.functionCall && !p.functionResponse) {
        p.text = v;
        return true;
      }
    }
    return false;
  }
  setMsgText(m, v);
  return true;
}

/* 收集整个请求体中（剔除我们自己的 AR-NAR/AR-USR 后）的预设文本，供「礼让预设」探测重复条目 */
function narrCollectPresetText(body) {
  var chunks = [];
  try {
    var root = (body && body.request && typeof body.request === 'object' && !Array.isArray(body.request)) ? body.request : body;
    if (!root || typeof root !== 'object') return '';
    if (typeof root.system === 'string') chunks.push(root.system);
    else if (Array.isArray(root.system)) {
      for (var si = 0; si < root.system.length; si++) {
        if (root.system[si] && typeof root.system[si].text === 'string') chunks.push(root.system[si].text);
      }
    }
    if (root.systemInstruction && Array.isArray(root.systemInstruction.parts)) {
      for (var gi = 0; gi < root.systemInstruction.parts.length; gi++) {
        if (root.systemInstruction.parts[gi] && typeof root.systemInstruction.parts[gi].text === 'string') {
          chunks.push(root.systemInstruction.parts[gi].text);
        }
      }
    }
    if (root.system_instruction && Array.isArray(root.system_instruction.parts)) {
      for (var g2 = 0; g2 < root.system_instruction.parts.length; g2++) {
        if (root.system_instruction.parts[g2] && typeof root.system_instruction.parts[g2].text === 'string') {
          chunks.push(root.system_instruction.parts[g2].text);
        }
      }
    }
    var listInfo = narrMsgList(body);
    if (listInfo) {
      var arr = listInfo.arr;
      for (var i = 0; i < arr.length; i++) {
        var m = arr[i];
        if (!m) continue;
        var r = String(m.role || '').toLowerCase();
        if (r === 'assistant' || r === 'model') continue;
        var tx = narrStrip(narrMsgText(m, listInfo.proto));
        if (tx) chunks.push(tx);
      }
    }
  } catch (eC) {}
  return chunks.join('\n');
}

function narrPresetHasKnow(body) {
  try { return NARR_PRESET_KNOW_RE.test(narrCollectPresetText(body)); } catch (e) { return false; }
}
function narrPresetHasCharm(body) {
  try { return NARR_PRESET_CHARM_RE.test(narrCollectPresetText(body)); } catch (e) { return false; }
}

/* ---------------- 真玩家发言楼层识别（绝不误包预设伪 user 规则块） ---------------- */

function narrRecentChatUserTexts() {
  var out = [];
  try {
    var c = stCtx();
    var ch = c && Array.isArray(c.chat) ? c.chat : null;
    if (!ch || !ch.length) return out;
    for (var i = ch.length - 1; i >= 0 && out.length < 8; i--) {
      var it = ch[i];
      if (!it || !it.is_user || it.is_system) continue;
      var s = String(it.mes == null ? '' : it.mes).trim();
      if (s) out.push(s);
    }
  } catch (e) {}
  return out;
}

/* 光域预设玩家输入边界外壳：<lk_user_turn>（V0.1）与 <lk_current_input>/<lk_history_input>（V0.2）（真玩家楼层，绝非预设控制块） */
var NARR_USER_TURN_RE = /^\s*<(lk_(?:user_turn|current_input|history_input))(?:\s[^>]*)?>([\s\S]*?)<\/\1>\s*$/i;
function narrStripUserTurnShell(s) {
  var t = String(s == null ? '' : s).trim();
  var m = NARR_USER_TURN_RE.exec(t);
  return m ? String(m[2] || '').trim() : t;
}

function narrMatchesRecentChat(text, chatUsers) {
  if (!chatUsers || !chatUsers.length) return false;
  var t = String(text || '').trim();
  if (!t) return false;
  var inner = narrStripUserTurnShell(t);
  for (var i = 0; i < chatUsers.length; i++) {
    var cu = chatUsers[i];
    if (t === cu || (inner && inner === cu)) return true;
    /* 兼容酒馆前缀 "UserName: 正文" 或轻微前后裁剪 */
    if (cu.length >= 6 && t.indexOf(cu) >= 0 && t.length <= cu.length + 60) return true;
    if (t.length >= 6 && cu.indexOf(t) >= 0 && cu.length <= t.length + 60) return true;
    if (inner && cu.length >= 6 && inner.indexOf(cu) >= 0 && inner.length <= cu.length + 60) return true;
    if (inner && inner.length >= 6 && cu.indexOf(inner) >= 0 && cu.length <= inner.length + 60) return true;
  }
  return false;
}

function narrIsPresetControlUserMsg(cleanText, msg, chatUsers) {
  if (!msg) return true;
  if (typeof lkIsProtectedMsg === 'function' && lkIsProtectedMsg(msg)) return true;
  /* Gemini functionResponse / inlineData 保护 */
  if (Array.isArray(msg.parts)) {
    for (var pi = 0; pi < msg.parts.length; pi++) {
      var pp = msg.parts[pi];
      if (pp && (pp.functionResponse || pp.functionCall)) return true;
    }
  }
  var t = String(cleanText || '').trim();
  if (!t) return true;
  var isUserTurnWrapped = NARR_USER_TURN_RE.test(t);
  var checkTxt = isUserTurnWrapped ? narrStripUserTurnShell(t) : t;
  if (!checkTxt) return true;
  /* 若精准命中酒馆聊天记录里的真实玩家发言，直接放行（绝不误杀） */
  if (narrMatchesRecentChat(t, chatUsers) || (isUserTurnWrapped && narrMatchesRecentChat(checkTxt, chatUsers))) return false;
  if (!isUserTurnWrapped && NARR_CTRL_HEAD_RE.test(checkTxt)) return true;
  if (NARR_CTRL_BODY_RE.test(checkTxt)) return true;
  /* 孤立闭合标签或末尾挂有未闭合起笔开标签的预设预填桥接尾块 */
  if (!isUserTurnWrapped && /^<\/[a-zA-Z0-9_\u4e00-\u9fa5~-]+>\s*$/.test(checkTxt)) return true;
  var tailOpen = isUserTurnWrapped ? null : NARR_UNCLOSED_TAIL_TAG_RE.exec(checkTxt);
  if (tailOpen) {
    var tagNm = String(tailOpen[1] || '').toLowerCase();
    if (tagNm !== 'user' && tagNm !== 'char' && checkTxt.toLowerCase().indexOf('</' + tagNm + '>') < 0) return true;
  }
  /* 超长结构化 Markdown 规则清单（预设 system-in-user 典型形态） */
  if (checkTxt.length > 1400) {
    var ruleHits = checkTxt.match(/^(?:#{1,4}\s+|[-*]\s+.*(?:严禁|禁止|必须|规则|视角|格式|原则|准则))/gm);
    if (ruleHits && ruleHits.length >= 4) return true;
  }
  return false;
}

/* 剥离末尾已挂载的其它脚本/插件尾块（AR-TRUNC / AR-OOC / 外部导演卡 / 定时提醒），避免把它们误包进 <<<ACT>>> 或干扰真楼层匹配 */
function narrSplitExternalTails(s) {
  var core = String(s == null ? '' : s);
  var tails = [];
  var pairs = [
    ['〔AR-TRUNC', '〔/AR-TRUNC〕'],
    ['〔AR-OOC', '〔/AR-OOC〕'],
    ['<下轮导演卡>', '</下轮导演卡>'],
    ['<定时提醒>', '</定时提醒>'],
    ['<定时注入提示词>', '</定时注入提示词>']
  ];
  for (var guard = 0; guard < 8; guard++) {
    var cut = false;
    var trimmed = core.replace(/[ \t\r\n]+$/, '');
    for (var p = 0; p < pairs.length; p++) {
      var openMark = pairs[p][0], closeMark = pairs[p][1];
      if (trimmed.length >= closeMark.length && trimmed.slice(-closeMark.length) === closeMark) {
        var oi = (openMark === '〔AR-OOC') ? trimmed.indexOf(openMark) : trimmed.lastIndexOf(openMark);
        if (oi >= 0) {
          tails.unshift(trimmed.slice(oi));
          core = trimmed.slice(0, oi).replace(/[ \t\r\n]+$/, '');
          cut = true;
          break;
        }
      }
    }
    if (!cut) break;
  }
  return { core: core, tail: tails.join('\n\n') };
}

/* 返回按“从新到旧”排序的真实玩家 user 消息下标数组（depth 0, 1, 2...） */
function narrFindRealUserIndices(listInfo) {
  var arr = listInfo.arr, proto = listInfo.proto;
  var chatUsers = narrRecentChatUserTexts();
  var matchedChat = [];
  var real = [];
  var fallback = [];
  for (var i = arr.length - 1; i >= 0; i--) {
    var m = arr[i];
    if (!narrMsgIsUser(m, proto)) continue;
    if (typeof lkIsProtectedMsg === 'function' && lkIsProtectedMsg(m)) continue;
    var raw = narrMsgText(m, proto);
    var clean = narrStrip(raw);
    if (!clean.trim()) continue;
    fallback.push(i);
    var coreForMatch = (typeof narrSplitExternalTails === 'function') ? narrSplitExternalTails(clean).core : clean;
    if (chatUsers.length && (narrMatchesRecentChat(coreForMatch, chatUsers) || narrMatchesRecentChat(clean, chatUsers))) {
      matchedChat.push(i);
      real.push(i);
      continue;
    }
    if (!narrIsPresetControlUserMsg(clean, m, chatUsers)) {
      real.push(i);
    }
  }
  /* 若已通过 ST 聊天记录精确命中真实玩家楼层，则仅信任这些已核验楼层，彻底杜绝任何预设合成 user 块被误包 */
  if (matchedChat.length) return { real: matchedChat, fallback: fallback };
  return { real: real, fallback: fallback };
}

/* ---------------- 主注入入口（只改传入的 body 副本） ---------------- */

function narrApply(body) {
  var out = [];
  NARR_RT.yieldKnow = false;
  NARR_RT.yieldCharm = false;
  NARR_RT.wrappedCount = 0;
  NARR_RT.lastMode = '';

  if (!body || typeof body !== 'object') return out;
  var listInfo = narrMsgList(body);
  if (!listInfo || !listInfo.arr.length) return out;
  var arr = listInfo.arr, proto = listInfo.proto;

  /* 1) 先把所有 user 消息上的旧 AR-NAR / AR-USR 块剥净还原（保证幂等 + 关闭开关时彻底清干净） */
  var hadAnyOld = false;
  var cleanedAny = false;
  for (var c0 = 0; c0 < arr.length; c0++) {
    var mc = arr[c0];
    if (!narrMsgIsUser(mc, proto)) continue;
    var old0 = narrMsgText(mc, proto);
    if (old0.indexOf('〔' + NARR_TAG) >= 0 || old0.indexOf('〔' + NARR_USR_TAG) >= 0) {
      hadAnyOld = true;
      var base0 = narrStrip(old0);
      if (base0 !== old0) {
        narrSetMsgText(mc, base0, proto);
        cleanedAny = true;
      }
    }
  }

  /* 2) 非故事元模式避让 & 「预设适配 = 礼让预设」单维避重 */
  var presetTextAll = narrCollectPresetText(body);
  if (NARR_META_MODE_RE.test(presetTextAll)) {
    if (cleanedAny) out.push('叙述:清掉');
    else out.push('叙述:元模式避让');
    return out;
  }
  var forceMode = (typeof presetCompatForce === 'function') ? presetCompatForce() : true;
  var wantKnow = narrPick(cfg && cfg.know) !== 'off';
  var wantCharm = narrPick(cfg && cfg.charm) !== 'off';
  var skipKnow = false, skipCharm = false;
  if (!forceMode) {
    /* 双生协议防死锁：《光域·镜界》的独立防线 base_standalone_guard 已让位给卢克时，不被其思维链清单词误判为需要礼让 */
    var prismHandedToLuke = false;
    try {
      if (typeof isPrismPresetActive === 'function' && isPrismPresetActive()) {
        var pSnap = (typeof prismCollectSnapshot === 'function') ? prismCollectSnapshot() : null;
        if (!pSnap || !pSnap.enabledMap || !pSnap.enabledMap.base_standalone_guard) {
          prismHandedToLuke = true;
        }
      }
    } catch (ePrY) {}
    if (!prismHandedToLuke) {
      if (wantKnow && NARR_PRESET_KNOW_RE.test(presetTextAll)) { skipKnow = true; NARR_RT.yieldKnow = true; }
      if (wantCharm && NARR_PRESET_CHARM_RE.test(presetTextAll)) { skipCharm = true; NARR_RT.yieldCharm = true; }
    }
  }

  var block = narrBody({ skipKnow: skipKnow, skipCharm: skipCharm, skipLethal: skipCharm });
  var doWrap = !skipCharm && narrCharmWrapOn();
  var lethal = !skipCharm && narrCharmLethalOn();

  if (!block && !doWrap) {
    if (cleanedAny) out.push('叙述:清掉');
    else if (skipKnow || skipCharm) out.push('叙述:礼让预设');
    return out;
  }

  /* 3) 定位真实玩家 user 楼层 */
  var found = narrFindRealUserIndices(listInfo);
  var wrapIdxs = [];
  if (doWrap && found.real.length) {
    var maxWrap = NARR_WRAP_MAX_DEPTH + 1;
    for (var wi = 0; wi < found.real.length && wi < maxWrap; wi++) {
      wrapIdxs.push(found.real[wi]);
    }
  }

  /* 规则块落点：优先最新真实玩家 user；若全部都是合成/规则消息，兜底落到最后一条非受保护 user */
  var ruleIdx = found.real.length ? found.real[0] : (found.fallback.length ? found.fallback[0] : -1);

  /* 4) 执行近 2 轮三明治贴脸包裹（depth 0 全量，depth 1~2 轻量） */
  var wrappedN = 0;
  var savedTails = {};
  for (var wj = 0; wj < wrapIdxs.length; wj++) {
    var idxW = wrapIdxs[wj];
    var mW = arr[idxW];
    var baseW = narrMsgText(mW, proto);
    if (!baseW.trim()) continue;
    var spW = narrSplitExternalTails(baseW);
    if (!spW.core.trim()) continue;
    if (spW.tail) savedTails[idxW] = spW.tail;
    var wrappedTxt = narrWrapUserText(spW.core, wj === 0, lethal);
    var finalW = wrappedTxt;
    if (spW.tail && idxW !== ruleIdx) finalW += '\n\n' + spW.tail;
    if (finalW !== baseW) {
      narrSetMsgText(mW, finalW, proto);
      wrappedN++;
    }
  }
  NARR_RT.wrappedCount = wrappedN;

  /* 5) 执行规则块注入（紧跟在末条玩家消息末尾，位于外部尾块 AR-TRUNC / AR-OOC 之前） */
  var wroteRule = false;
  if (ruleIdx >= 0) {
    var mR = arr[ruleIdx];
    var curR = narrMsgText(mR, proto);
    var ruleTail = savedTails[ruleIdx] || '';
    if (!ruleTail) {
      var spR = narrSplitExternalTails(curR);
      if (spR.tail) { curR = spR.core; ruleTail = spR.tail; }
    }
    var nextR = curR;
    if (block) {
      var sep = '';
      if (nextR) sep = /\n$/.test(nextR) ? '\n' : '\n\n';
      nextR = nextR + sep + block;
      wroteRule = true;
    }
    if (ruleTail) nextR = nextR + (nextR ? '\n\n' : '') + ruleTail;
    if (nextR !== narrMsgText(mR, proto)) {
      narrSetMsgText(mR, nextR, proto);
    }
  }

  if (wroteRule || wrappedN > 0) {
    var tags = [];
    if (!skipKnow && wantKnow) tags.push('防全知' + narrTag(cfg.know));
    if (!skipCharm && wantCharm) {
      var ct = '去媚' + narrTag(cfg.charm);
      if (wrappedN > 0) ct += '·包裹' + wrappedN;
      if (lethal) ct += '·致命';
      tags.push(ct);
    }
    var lbl = tags.join('+') || narrLabel();
    NARR_RT.lastMode = lbl;
    out.push('叙述:' + lbl);
  } else if (hadAnyOld && cleanedAny) {
    out.push('叙述:清掉');
  }
  return out;
}

/* ===== 15_ooc.js ===== */
/* 15_ooc.js — v0.76 反 OOC：点名 / 反模板 / 变更门槛 / 口吻一致
 *
 * 四件事，四个开关，各管各的：
 *   点名      —— 先认出这一轮在场的是谁，再让他们各自对照世界书；
 *   反模板    —— 同一类情绪别用现成的动作包（眼底闪过、嘴角勾起…）；
 *   变更门槛  —— 态度 / 关系 / 立场变了，要指得出是哪件事改的；
 *   口吻一致  —— 说话方式、称呼、口癖跟前文一致（换人检验）。
 *
 * 三条不变量（与 12_narr.js 同）：
 *   1) 预设只读：这里只决定自己注不注，从不删改请求体里预设的任何内容；
 *   2) 幂等：注入前先剥掉上一次的块，注一次和注十次结果完全一样；
 *   3) 失败安全：任何一步抛错都退化成「什么都不注」，绝不让它弄坏正常请求。
 *
 * 注入通道：优先酒馆自己的扩展提示位（setExtensionPrompt，IN_CHAT / depth 4）；
 * 宿主没有这个方法时回落成「贴末条 user 消息尾部」，与叙述层同一位置。
 *   ★ 扩展提示位是宿主持久保存的：写进去之后由宿主自己在下一轮拼提示时带上，
 *     所以这条路径不改请求体、也不会和回落路径同时生效（oocApply 返回 true 时
 *     planRequest 不会再调 oocBodyPatch）。
 *
 * 世界书：只读 ctx.characters[this_chid].data.extensions.world → loadWorldInfo(book)。
 *   loadWorldInfo 在部分版本上是 Promise，这里只吃同步返回值；拿到 Promise 就当
 *   拿不到（宁可这一轮不点名，也不把请求挂死）。
 */

var OOC_TAG = '〔AR-OOC 1.0〕';
var OOC_CLOSE = '〔/AR-OOC〕';
var OOC_KEY = 'ar6.ooc';
var OOC_ITEMS = ['roll', 'tpl', 'chg', 'voice'];
var OOC_CFGKEY = { roll: 'oocRoll', tpl: 'oocTpl', chg: 'oocChg', voice: 'oocVoice' };
var OOC_LABEL = { roll: '点名', tpl: '反模板', chg: '变更门槛', voice: '口吻一致' };

/* ---------------- 文案 ----------------
   四段各自成块，各自带同一个头（OOC_TAG），中间空一行。
   面板预览与注入用的是同一份文案，不许只改一边：
   改一个字，用户面板上看到的和这里给的就不是同一份东西了。
   {{user}} 原样保留，输出前由 oocFill() 换成真名（拿不到就换「你」）。 */
var OOC_SEG_TPL = OOC_TAG + '\n' +
  '同一类情绪，不要用现成的动作包打发——眼底闪过、嘴角勾起、喉结滚动、\n' +
  '呼吸一滞、身子一僵，这类动作谁都能做，写了等于没写。\n' +
  '\n' +
  '不要用一句话概括一个人的全部性格，也不要让他只当「那个温柔的人」。\n' +
  '\n' +
  '他做的动作，得是这个人做得出来的动作。';

var OOC_SEG_CHG = OOC_TAG + '\n' +
  '一个人对另一个人的态度、关系、立场变了，要指得出是哪件事改变的、中间经过什么。\n' +
  '\n' +
  '说不出缘由的变化，不要写。';

var OOC_SEG_VOICE = OOC_TAG + '\n' +
  '他的说话方式、称呼、口癖、句子长短，跟前文保持一致。\n' +
  '\n' +
  '检验方法：把这句话换给另一个人说，如果照样成立，那就是写错了，重写。';

/* 点名：名单由调用方拼，「、」连接 + 「。」 */
function oocRollSeg(names) {
  var list = String((names || []).join('、')).replace(/[、\s]+$/, '');
  return OOC_TAG + '\n' +
    '本轮涉及的角色：' + list + '。\n' +
    '\n' +
    '动笔前，逐一对照世界书里他们各自的条目——\n' +
    '他怎么说话、对{{user}}是什么态度、什么事他不会做。\n' +
    '\n' +
    '世界书写了的，以世界书为准；世界书没写的，按前文已经写过的演，不要改。';
}

/* ---------------- 配置 ---------------- */

function oocFlag(v, dflt) {
  if (v === undefined || v === null) return dflt;
  return !!v;
}

/* 总闸关 → 返回 null（调用方一律当「什么都不做」）。
   注意：读的是 cfg 里的存值；CFG_DEFAULT 的默认值是 off，迁移不重跑。 */
function oocCfg() {
  var c = (cfg && typeof cfg === 'object') ? cfg : null;
  if (!c) return null;
  if (String(c.ooc == null ? 'off' : c.ooc) !== 'on') return null;
  return {
    roll: oocFlag(c.oocRoll, true),
    tpl: oocFlag(c.oocTpl, true),
    chg: oocFlag(c.oocChg, false),
    voice: oocFlag(c.oocVoice, true)
  };
}

/* 单项是否开着（面板渲染用；总闸关时一律当关） */
function oocOnOf(item) {
  var c = oocCfg();
  if (!c) return false;
  return !!c[item];
}

/* ---------------- 宿主上下文（老 ST 可能什么都没有） ---------------- */

function oocCtx() {
  try {
    if (typeof stCtx === 'function') {
      var c = stCtx();
      if (c) return c;
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e1) {}
  return null;
}

/* 这个角色绑的世界书名；没绑返回空串 */
function oocBook() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var list = c.characters;
    var id = c.this_chid;
    if (list == null || id == null || id === '') return '';
    var n = +id;
    if (!isFinite(n) || n < 0) return '';
    var ch = list[n];
    if (!ch) return '';
    var d = ch.data;
    var ext = d && d.extensions;
    var w = ext && ext.world;
    return String(w == null ? '' : w).trim();
  } catch (e) { return ''; }
}

/* 世界书条目 → 人物名单。只认两种写法：
   P1  comment 带 [角色] / [人物] / [NPC] … 前缀；
   P2  comment 本身就是 2~6 字的纯名字，且每个 key 也都是 2~6 字纯名字。 */
var OOC_NAME_RE = /^[\u4e00-\u9fa5A-Za-z·]{2,6}$/;
var OOC_P1_RE = /^\[(角色|人物|NPC|npc|char|Char)\]\s*/;

function oocTrim(s) {
  return String(s == null ? '' : s).replace(/^[\s\u3000]+|[\s\u3000]+$/g, '');
}

function oocKeys(e) {
  var out = [];
  if (!e || !Array.isArray(e.key)) return out;
  for (var i = 0; i < e.key.length; i++) {
    var k = oocTrim(e.key[i]);
    if (!k) continue;
    if (out.indexOf(k) < 0) out.push(k);
  }
  return out;
}

/* 世界书数据的同步缓存。
   新版酒馆的 ctx.loadWorldInfo 返回 Promise，同步路径拿不到；这里把 Promise
   的结果回填进来，下一次渲染 / 下一轮请求就能用（TTL 30 秒，改完世界书不用刷新）。
   key 是书名；只缓存成功解析过的整本数据。 */
var OOC_BOOK_CACHE = {};
var OOC_BOOK_WAIT = {};
var OOC_BOOK_TTL = 30000;

function oocBookCached(book, c) {
  var hit = OOC_BOOK_CACHE[book];
  if (hit) {
    if ((Date.now() - hit.at) < OOC_BOOK_TTL) return hit.data;
    delete OOC_BOOK_CACHE[book];
  }
  var data;
  try { data = c.loadWorldInfo(book); } catch (e0) { return null; }
  if (data && typeof data.then === 'function') {
    /* Promise 不认识，也没法在这里 await —— 挂一次 then 回填，这一轮先当拿不到 */
    if (!OOC_BOOK_WAIT[book]) {
      OOC_BOOK_WAIT[book] = 1;
      try {
        data.then(function (d) {
          delete OOC_BOOK_WAIT[book];
          if (d && typeof d === 'object') OOC_BOOK_CACHE[book] = { data: d, at: Date.now() };
        }, function () { delete OOC_BOOK_WAIT[book]; });
      } catch (e1) { delete OOC_BOOK_WAIT[book]; }
    }
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  return data;
}

function oocPeople(bookName) {
  var out = [];
  var book = oocTrim(bookName);
  if (!book) return out;
  var c = oocCtx();
  if (!c || typeof c.loadWorldInfo !== 'function') return out;
  var data = oocBookCached(book, c);
  if (!data) return out;
  var ent = data.entries;
  if (!ent || typeof ent !== 'object') return out;

  var seen = {};
  var i, e, cm, nm, keys, m;
  var uids = [];
  if (Array.isArray(ent)) {
    for (i = 0; i < ent.length; i++) uids.push(i);
  } else {
    for (var k in ent) if (Object.prototype.hasOwnProperty.call(ent, k)) uids.push(k);
  }

  for (i = 0; i < uids.length && out.length < 40; i++) {
    e = ent[uids[i]];
    if (!e || typeof e !== 'object') continue;
    if (e.disable === true) continue;
    cm = oocTrim(e.comment);
    if (!cm) continue;
    nm = '';
    keys = oocKeys(e);
    m = OOC_P1_RE.exec(cm);
    if (m) {
      nm = oocTrim(cm.slice(m[0].length));
      if (!nm) continue;
    } else if (OOC_NAME_RE.test(cm) && keys.length) {
      var ok = true;
      for (var j = 0; j < keys.length; j++) {
        if (!OOC_NAME_RE.test(keys[j])) { ok = false; break; }
      }
      if (!ok) continue;
      nm = cm;
    } else {
      continue;
    }
    if (seen[nm]) continue;
    seen[nm] = 1;
    out.push({ name: nm, keys: keys });
  }
  return out;
}

/* 在场：按 key 在最近两条消息里出现几次排序，取前 6。
   次数相同按世界书里的先后，保证同一段对话里名单稳定。 */
function oocPresent(people, text) {
  var out = [];
  if (!people || !people.length) return out;
  var t = String(text == null ? '' : text);
  if (!t) return out;
  var hit = [];
  for (var i = 0; i < people.length; i++) {
    var p = people[i];
    if (!p) continue;
    var ks = p.keys || [];
    var n = 0;
    for (var j = 0; j < ks.length; j++) {
      var k = String(ks[j] == null ? '' : ks[j]);
      if (!k) continue;
      var at = t.indexOf(k);
      while (at >= 0) {
        n++;
        at = t.indexOf(k, at + k.length);
        if (n > 99) break;
      }
    }
    if (n > 0) hit.push({ name: String(p.name || ''), n: n, i: i });
  }
  if (!hit.length) return out;
  hit.sort(function (a, b) { return (b.n - a.n) || (a.i - b.i); });
  for (var q = 0; q < hit.length && q < 6; q++) out.push(hit[q].name);
  return out;
}

/* 最近两条消息的正文；ctx.chat 不可用时返回空串 */
function oocRecent() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var ch = c.chat;
    if (!ch || !ch.length) return '';
    var from = ch.length - 2;
    if (from < 0) from = 0;
    var parts = [];
    for (var i = from; i < ch.length; i++) {
      var m = ch[i];
      if (!m) continue;
      parts.push(String(m.mes == null ? '' : m.mes));
    }
    return parts.join('\n');
  } catch (e) { return ''; }
}

/* ---------------- 冲突选项（只在本会话内，不落配置） ----------------
   'script' = 用我们的；'preset' = 听预设的（这一段就不注了）。 */
var OOC_CHOICE = {};

function oocChoice(item) {
  var v = OOC_CHOICE[String(item == null ? '' : item)];
  return (v === 'script' || v === 'preset') ? v : '';
}

function oocSetChoice(item, v) {
  var k = String(item == null ? '' : item);
  if (OOC_ITEMS.indexOf(k) < 0) return '';
  if (v !== 'script' && v !== 'preset') { delete OOC_CHOICE[k]; return ''; }
  OOC_CHOICE[k] = v;
  return v;
}

function oocResetChoice() {
  for (var i = 0; i < OOC_ITEMS.length; i++) delete OOC_CHOICE[OOC_ITEMS[i]];
}

/* ---------------- 拼接 ---------------- */

/* {{user}} → 真名（拿不到就用「你」）。这里不碰尖括号，文案里也没有 <user>。 */
function oocFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('{{user}}') < 0) return s;
  var n = '';
  try { if (typeof narrUserName === 'function') n = narrUserName(); } catch (e) {}
  return s.split('{{user}}').join(n || '你');
}

/* 这一轮要注的整块；总闸关 / 四项全关时返回空串 */
function oocText() {
  var c = oocCfg();
  if (!c) return '';
  var parts = [];

  /* 先算「这一轮提到了谁」。世界书里一个人物都认不出来时不做拦截
     （可能是没绑世界书，不能因此把功能关掉）；但只要认得出人物、
     而最近两条消息里一个都没提到，就整块不注——没人在场的时候
     跟模型讲「别写 OOC」只是噪音，还白花 token。 */
  var names = [];
  var known = 0;
  try {
    var book = oocBook();
    if (book) {
      var people = oocPeople(book);
      known = people.length;
      if (known) names = oocPresent(people, oocRecent());
    }
  } catch (e0) { names = []; known = 0; }
  if (known > 0 && !names.length) return '';

  /* 1) 点名：认不出人就不注这一段（写「本轮涉及的角色：。」没有意义） */
  if (c.roll && oocChoice('roll') !== 'preset') {
    if (names.length) parts.push(oocFill(oocRollSeg(names)));
  }

  /* 2~4) 反模板 → 变更门槛 → 口吻一致（顺序固定，别按开关顺序拼） */
  if (c.tpl && oocChoice('tpl') !== 'preset') parts.push(oocFill(OOC_SEG_TPL));
  if (c.chg && oocChoice('chg') !== 'preset') parts.push(oocFill(OOC_SEG_CHG));
  if (c.voice && oocChoice('voice') !== 'preset') parts.push(oocFill(OOC_SEG_VOICE));

  return parts.length ? (parts.join('\n\n') + '\n' + OOC_CLOSE) : '';
}

/* 粗估 token（中文约 0.7 tok/字），只给面板一个量级 */
function oocTokens() {
  var t = '';
  try { t = oocText(); } catch (e) { t = ''; }
  return t ? Math.round(t.length * 0.7) : 0;
}

function oocLabel() {
  var c = oocCfg();
  if (!c) return '关';
  var out = [];
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k] || oocChoice(k) === 'preset') continue;
    out.push(OOC_LABEL[k]);
  }
  return out.length ? out.join('+') : '关';
}

/* ---------------- 注入 ---------------- */

/* 剥掉上一次注入的块。
   我们的块永远是整块贴在尾部（四段各带同一个头，块内没有别人的东西），
   所以从第一个标记砍到结尾即可；剥完把尾部空白收掉，免得每轮多一行空行。 */
function oocStrip(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf(OOC_TAG);
  if (i < 0) return t;
  var j = t.indexOf(OOC_CLOSE, i);
  if (j < 0) return t.slice(0, i).replace(/[ \t\r\n]+$/, '');
  var head = t.slice(0, i).replace(/[ \t\r\n]+$/, '');
  var tail = t.slice(j + OOC_CLOSE.length).replace(/^[ \t\r\n]+/, '');
  if (!tail) return head;
  return head + (head ? '\n\n' : '') + tail;
}

/* 扩展提示位通道：拿得到 ctx 且它真的有 setExtensionPrompt 才算 */
function oocChannel() {
  try {
    var c = oocCtx();
    if (c && typeof c.setExtensionPrompt === 'function') return c;
  } catch (e) {}
  return null;
}

/* 写扩展提示位。true = 这一次走的就是这条通道；false = 交给 oocBodyPatch 回落。
   文本为空时写空串，等于把上一轮留下的块清掉（不然关掉总闸之后它还在）。 */
function oocApply() {
  var text = '';
  try { text = oocText(); } catch (e0) { text = ''; }
  var c = oocChannel();
  if (!c) return false;
  try {
    c.setExtensionPrompt(OOC_KEY, text, 1, 4, false, 0);
    return true;
  } catch (e1) { return false; }
}

/* 回落通道：贴到最后一条 role==='user' 的 content 尾部（与 narrApply 同一位置）。
   只改传进来的 body 副本，聊天记录一个字节都不动。
   返回改动描述数组，调用方必须 push 到 out.changed，否则不会序列化。 */
function oocBodyPatch(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  var idx = -1;
  try {
    if (typeof narrFindRealUserIndices === 'function') {
      var nfO = narrFindRealUserIndices({ arr: msgs, proto: 'messages' });
      if (nfO && nfO.real && nfO.real.length) idx = nfO.real[0];
    }
  } catch (eNfO) {}
  if (idx < 0) {
    for (var i = msgs.length - 1; i >= 0; i--) {
      var m = msgs[i];
      if (m && String(m.role || '') === 'user' && !(typeof lkIsProtectedMsg === 'function' && lkIsProtectedMsg(m))) { idx = i; break; }
    }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = '';
  try { old = String(textOfMsg(m2) || ''); } catch (e0) { old = ''; }
  var base = oocStrip(old);
  var block = '';
  try { block = oocText(); } catch (e1) { block = ''; }

  if (!block) {
    if (base !== old) {
      try { setMsgText(m2, base); } catch (e2) { return out; }
      out.push('反OOC:清掉');
    }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    try { setMsgText(m2, next); } catch (e3) { return out; }
    out.push('反OOC:' + oocLabel());
  }
  return out;
}

/* ---------------- 预设签名：预设是不是已经自带同类指令 ----------------
   §1 的四组关键词，只认有没有，不认强弱。扫的是「真正启用」的条目：
   prompt_order[].order[] 里 enabled===true 的，用 .identifier 映射回 prompts[i]，
   映射不上就按同一位置的索引对齐（老预设没有 identifier）。 */
var OOC_SIG_WORDS = {
  tpl: ['模板', '脸谱', '刻板', '桥段', 'stereotyp', 'trope', 'cliché'],
  chg: ['变化', '缘由', '转变', '动机', 'event', 'process'],
  voice: ['口吻', '说话方式', '口头禅', 'voice', 'tone', 'speech pattern'],
  roll: ['世界书', '人设', '角色设定', 'lorebook', 'persona']
};

function oocHitWord(words, text) {
  var s = String(text == null ? '' : text).toLowerCase();
  for (var i = 0; i < words.length; i++) {
    var w = String(words[i] || '').toLowerCase();
    if (w && s.indexOf(w) >= 0) return w;
  }
  return '';
}

function oocSigName(p, text) {
  var nm = oocTrim(p && (p.name || p.identifier));
  var sn = String(text == null ? '' : text).replace(/\s+/g, ' ').replace(/^[\s\u3000]+/, '').slice(0, 20);
  if (nm && sn) return nm + ' · ' + sn;
  return nm || sn;
}

/* 当前预设对象；拿不到就返回 null（拿不到 = 不弹窗，不会误判） */
function oocPreset() {
  try {
    var c = oocCtx();
    if (c) {
      if (c.preset && Array.isArray(c.preset.prompt_order)) return c.preset;
      if (c.presetManager && Array.isArray(c.presetManager.prompt_order)) return c.presetManager;
      if (typeof c.getPresetManager === 'function') {
        var pm = c.getPresetManager();
        if (pm && Array.isArray(pm.prompt_order)) return pm;
      }
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getPresetManager === 'function') {
      var pm2 = st.getPresetManager();
      if (pm2 && Array.isArray(pm2.prompt_order)) return pm2;
    }
  } catch (e1) {}
  return null;
}

function oocMatchPrompt(prompts, o, j) {
  var id = (o && o.identifier != null) ? String(o.identifier) : '';
  if (id) {
    for (var i = 0; i < prompts.length; i++) {
      var p = prompts[i];
      if (p && String(p.identifier == null ? '' : p.identifier) === id) return p;
    }
  }
  var q = prompts[j];
  return (q && typeof q === 'object') ? q : null;
}

function oocSig(preset) {
  var sig = { tpl: false, chg: false, voice: false, roll: false, hits: {} };
  var p = null;
  try { p = preset || oocPreset(); } catch (e0) { p = null; }
  if (!p || typeof p !== 'object') return sig;
  var prompts = Array.isArray(p.prompts) ? p.prompts : [];
  var orders = Array.isArray(p.prompt_order) ? p.prompt_order : [];
  if (!orders.length) return sig;

  var used = {};
  for (var i = 0; i < orders.length; i++) {
    var ord = orders[i] && orders[i].order;
    if (!Array.isArray(ord)) continue;
    for (var j = 0; j < ord.length; j++) {
      var o = ord[j];
      if (!o || o.enabled !== true) continue;      /* 只认真正启用的条目 */
      var pr = oocMatchPrompt(prompts, o, j);
      if (!pr) continue;
      var mk = String(pr.identifier == null ? j : pr.identifier);
      if (used[mk]) continue;
      used[mk] = 1;
      var text = String(pr.content == null ? '' : pr.content);
      if (!text) continue;
      for (var t = 0; t < OOC_ITEMS.length; t++) {
        var k = OOC_ITEMS[t];
        if (sig[k]) continue;
        if (!oocHitWord(OOC_SIG_WORDS[k], text)) continue;
        sig[k] = true;
        sig.hits[k] = oocSigName(pr, text);
      }
    }
  }
  return sig;
}

/* 需要问的项：开着 + 预设也管了 + 还没定过。
   一旦用户勾了「以后都按这个来」（cfg.oocPolicy），就直接按全局策略落定，不再问。 */
function oocAsk() {
  var out = [];
  var c = oocCfg();
  if (!c) return out;
  var pol = String((cfg && cfg.oocPolicy) || '');
  if (pol !== 'script' && pol !== 'preset') {
    pol = (typeof presetCompatForce === 'function' && !presetCompatForce()) ? 'preset' : '';
  }
  var sig = null;
  try { sig = oocSig(); } catch (e0) { return out; }
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k]) continue;
    if (!sig[k]) continue;
    if (oocChoice(k)) continue;
    if (pol) { OOC_CHOICE[k] = pol; continue; }
    out.push(k);
  }
  return out;
}

/* ---------------- 面板 ---------------- */

/* 子 chip 上的字：开 / 关 / 听预设（听预设时 chip 本身置灰） */
var OOC_ICON = { roll: '🧩', tpl: '🚫', chg: '🔒', voice: '🗣' };

function oocChipLabel(item) {
  var k = String(item == null ? '' : item);
  var nm = OOC_LABEL[k] || k;
  var ic = OOC_ICON[k] || '🎛';
  if (oocChoice(k) === 'preset') return ic + ' ' + nm + ':听预设';
  return ic + ' ' + nm + ':' + (oocOnOf(k) ? '开' : '关');
}

/* 状态行：世界书 + 认出来几个人。只读，不改任何状态。 */
function oocStatusLine() {
  try {
    var book = oocBook();
    if (!book) return '这个角色没绑世界书';
    var people = oocPeople(book);
    if (!people.length) return '世界书：' + book + ' · 没认出人物条目';
    return '世界书：' + book + ' · 识别到 ' + people.length + ' 个人物';
  } catch (e) { return ''; }
}

/* ===== 5_route.js ===== */
/* ============================================================================
 * Anti-Route v7 — 5/6 Route
 * 渠道可验性门禁 / 别名钉死 / 瘦身报告 / 路由率 KPI / 档位可观测性检查
 * 原则：全部是「旁路探针 + 展示」，不在生成路径上加任何计算
 * ========================================================================== */

var CH_KEY = 'ar7.ch';
var ALIAS_CACHE = null;

/* ---------------- 渠道状态 ---------------- */

function chKeyOf(base, key) {
  return String(hashStr(String(base || '').replace(/\/+$/, '') + '|' + String(key || '')));
}

/* 当前渠道基址：优先面板里填的，其次用上一轮请求实际发往的 base */
function curBase() {
  var b = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (b) return b;
  try { if (lastReq && lastReq.base) return String(lastReq.base).replace(/\/+$/, ''); } catch (e) {}
  return '';
}

function readChAll() {
  try {
    var o = JSON.parse(ar6LsGet(CH_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeChAll(o) {
  try { ar6LsSet(CH_KEY, JSON.stringify(o)); } catch (e) {}
}

function chState() {
  var b = curBase();
  if (!b) return { echoes: null, at: 0, base: '' };
  var all = readChAll();
  var st = all[chKeyOf(b, '')];
  if (!st || typeof st !== 'object') return { echoes: null, at: 0, base: b };
  st.base = b;
  return st;
}

function setChState(st) {
  var b = curBase();
  if (!b) return false;
  var all = readChAll();
  var next = { echoes: st.echoes, at: nowMs(), base: b, note: st.note || '' };
  all[chKeyOf(b, '')] = next;
  writeChAll(all);
  return true;
}

/* 可验性标签：true=回显不可验 / false=可验 / null=未验 */
function verifiableLabel() {
  var st = chState();
  if (st.echoes === true) return '不可验';
  if (st.echoes === false) return '可验';
  return '未验';
}

function verifiableCode() {
  var st = chState();
  if (st.echoes === true) return 'no';
  if (st.echoes === false) return 'yes';
  return 'unknown';
}

/* ---------------- 最小探针 ---------------- */

function probeFetchFn() {
  try { if (typeof probeFetch === 'function' && probeFetch) return probeFetch; } catch (e) {}
  try { return HOST.fetch; } catch (e) { return null; }
}

function buildStBackendProbe(bodyObj) {
  try {
    if (cfg && cfg.dualBase) return null;
    if (!lastReq || !/\/api\/backends\/chat-completions\/generate\b/.test(String(lastReq.url || ''))) return null;
    var tpl = lastReq.raw ? JSON.parse(lastReq.raw) : null;
    if (!tpl || typeof tpl !== 'object' || Array.isArray(tpl)) return null;
    var payload = {};
    for (var k in tpl) {
      if (!Object.prototype.hasOwnProperty.call(tpl, k)) continue;
      if (k === 'messages' || k === 'contents' || k === 'tools' || k === 'tool_choice' ||
          k === 'functions' || k === 'function_call' || k === 'stop' || k === 'logit_bias' ||
          k === 'response_format' || k === 'generationConfig') continue;
      payload[k] = tpl[k];
    }
    var wantModel = String((bodyObj && bodyObj.model) || payload.model || '');
    payload.model = wantModel;
    var src = String(payload.chat_completion_source || '').toLowerCase();
    if (src === 'custom' || 'custom_model' in payload) payload.custom_model = wantModel;
    if (src === 'openai' && 'openai_model' in payload) payload.openai_model = wantModel;
    if (src === 'openrouter' && 'openrouter_model' in payload) payload.openrouter_model = wantModel;
    if (src === 'deepseek' && 'deepseek_model' in payload) payload.deepseek_model = wantModel;
    if (src === 'claude' && 'claude_model' in payload) payload.claude_model = wantModel;
    if (src === 'makersuite') {
      if ('google_model' in payload) payload.google_model = wantModel;
      if ('makersuite_model' in payload) payload.makersuite_model = wantModel;
    }
    if (src === 'vertexai' && 'vertexai_model' in payload) payload.vertexai_model = wantModel;
    payload.messages = (bodyObj && bodyObj.messages) || [{ role: 'user', content: 'ping' }];
    payload.max_tokens = (bodyObj && bodyObj.max_tokens) || 16;
    payload.stream = false;
    if (bodyObj && bodyObj.reasoning_effort) payload.reasoning_effort = bodyObj.reasoning_effort;

    var headers = { 'Content-Type': 'application/json', 'x-ar6-internal': '1' };
    try {
      var st = (HOST && HOST.SillyTavern) || (typeof SELF_WIN !== 'undefined' && SELF_WIN && SELF_WIN.SillyTavern);
      var ctx = st && typeof st.getContext === 'function' ? st.getContext() : null;
      if (ctx && typeof ctx.getRequestHeaders === 'function') {
        var stHd = ctx.getRequestHeaders();
        if (stHd && typeof stHd === 'object') {
          for (var hk in stHd) if (Object.prototype.hasOwnProperty.call(stHd, hk)) headers[hk] = stHd[hk];
        }
      }
    } catch (eHd) {}
    headers['x-ar6-internal'] = '1';
    return { url: lastReq.url, headers: headers, body: JSON.stringify(payload) };
  } catch (e) { return null; }
}

/* TT 酒馆 / 前端直连探针适配：仅在同源主机名一致时附带内存鉴权头，并自动适配 Gemini 原生 :generateContent 端点 */
function buildDirectProbe(rawUrl, bodyObj) {
  try {
    if (cfg && cfg.dualBase) return null;
    if (!lastReq || !lastReq.url || /\/api\/backends\/chat-completions\/generate\b/.test(String(lastReq.url))) return null;
    var pageHref = (HOST.location && HOST.location.href) || 'http://localhost';
    var uLast = new URL(String(lastReq.url), pageHref);
    var uTarget = new URL(String(rawUrl || lastReq.url), pageHref);
    if (uLast.origin !== uTarget.origin) return null;

    var headers = { 'Content-Type': 'application/json', 'x-ar6-internal': '1' };
    if (lastReq.authHeaders && typeof lastReq.authHeaders === 'object') {
      for (var ak in lastReq.authHeaders) {
        if (Object.prototype.hasOwnProperty.call(lastReq.authHeaders, ak) && lastReq.authHeaders[ak]) {
          headers[ak] = lastReq.authHeaders[ak];
        }
      }
    }

    /* 若上一轮是直连 Gemini 原生 :streamGenerateContent / :generateContent，则用原生格式发探针并保留 ?key=... */
    if (/\/models\/[^/?:]+:(?:streamGenerateContent|generateContent)/i.test(uLast.pathname)) {
      var wantModel = String((bodyObj && bodyObj.model) || lastReq.model || 'gemini-2.5-pro').replace(/^models\//i, '');
      var uNat = new URL(uLast.href);
      uNat.pathname = uLast.pathname.replace(/\/models\/[^/?:]+:(?:streamGenerateContent|generateContent)/i,
        '/models/' + encodeURIComponent(wantModel) + ':generateContent');
      try { uNat.searchParams.delete('alt'); } catch (eAlt) {}
      var promptTxt = 'ping';
      try {
        if (bodyObj && Array.isArray(bodyObj.messages) && bodyObj.messages.length) {
          var lastMsg = bodyObj.messages[bodyObj.messages.length - 1];
          if (lastMsg && typeof lastMsg.content === 'string' && lastMsg.content) promptTxt = lastMsg.content;
        }
      } catch (eMsg) {}
      var natBody = {
        contents: [{ role: 'user', parts: [{ text: promptTxt }] }],
        generationConfig: { maxOutputTokens: (bodyObj && bodyObj.max_tokens) || 16 }
      };
      return { url: uNat.href, headers: headers, body: JSON.stringify(natBody) };
    }

    return { url: rawUrl, headers: headers, body: JSON.stringify(bodyObj) };
  } catch (e) { return null; }
}

function probeOnce(url, bodyObj, ms) {
  var stProbe = buildStBackendProbe(bodyObj);
  var dirProbe = stProbe ? null : buildDirectProbe(url, bodyObj);
  var chosen = stProbe || dirProbe;
  var targetUrl = chosen ? ensureProbeUrl(chosen.url) : ensureProbeUrl(url);
  if (!targetUrl) return Promise.resolve({ status: 0, model: '', err: 'probe-not-approved' });
  return new Promise(function (resolve) {
    var done = false;
    var timer = setTimeout(function () {
      if (done) return;
      done = true;
      resolve({ status: 0, model: '', err: 'timeout' });
    }, ms || 20000);
    var f = probeFetchFn();
    if (!f) { clearTimeout(timer); resolve({ status: 0, model: '', err: 'no-fetch' }); return; }
    var init = chosen
      ? { method: 'POST', headers: chosen.headers, body: chosen.body }
      : { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-ar6-internal': '1' }, body: JSON.stringify(bodyObj) };

    var p;
    try {
      p = f.call(HOST, targetUrl, init);
    } catch (e) {
      clearTimeout(timer); resolve({ status: 0, model: '', err: 'throw' }); return;
    }
    Promise.resolve(p).then(function (res) {
      var out = { status: res.status, model: '', err: '', ctx: '' };
      return res.text().then(function (t) {
        out.raw = String(t || '').slice(0, 4000);
        try {
          var j = JSON.parse(t);
          out.model = String(j.modelVersion || j.model || (j.candidates && j.candidates[0] && j.candidates[0].modelVersion) || (j.message && j.message.model) || '');
          if (j.error) {
            out.err = typeof j.error === 'string' ? j.error.slice(0, 140) : String(j.error.message || j.error.code || JSON.stringify(j.error)).slice(0, 140);
          } else if (res.status >= 400 && j.message) {
            out.err = String(j.message).slice(0, 140);
          }
        } catch (e) {
          var m = /"(?:modelVersion|model)"\s*:\s*"([^"]{1,120})"/.exec(t || '');
          if (m) out.model = m[1];
          if (/131072|token count exceeds/i.test(t || '')) out.ctx = '131072';
          if (res.status >= 400 && !out.err) out.err = String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
        }
        return out;
      }).catch(function () { return out; });
    }).then(function (out2) {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve(out2);
    }).catch(function () {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve({ status: 0, model: '', err: 'network' });
    });
  });
}

/* 幽灵名探针：4xx ⇒ 按名分发（可验）；200 ⇒ 不读名字（回显） */
var PROBE_VERIFY_BUSY = false;
function runChannelVerify() {
  if (PROBE_VERIFY_BUSY) return Promise.resolve({ ok: false, msg: '探针正在运行，请等待上一次完成' });
  var base = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: '还没拿到渠道地址：请先正常发送一轮对话，再点真伪探针' });
  PROBE_VERIFY_BUSY = true;
  var real = String(cfg.alias || (lastReq && lastReq.model) || 'gemini-2.5-pro');
  var ghost = real + '-zzz-nonexistent';
  var url = openAIUrl(base);
  var body = {
    model: ghost,
    messages: [{ role: 'user', content: 'ping' }],
    max_tokens: 16,
    stream: false
  };
  return probeOnce(url, body, 20000).then(function (r) {
    var echoes = null, note = '', why = '';
    var msg = String((r && r.err) || '');
    if (r.status >= 400 && r.status < 500 && r.status !== 429) {
      if (r.status === 401 || r.status === 403) {
        why = 'auth';
        note = '认证被拒（HTTP ' + r.status + '）：请求未走到模型分发阶段，暂无法判定';
      } else if (r.status === 402) {
        why = 'quota';
        note = '额度或计费受限（HTTP 402）：暂无法判定';
      } else if (/model|not[\s_-]*found|does not exist|unknown|no such|invalid|unsupported|不存在|未找到|无可用渠道|no available/i.test(msg)) {
        why = 'rejected';
        echoes = false;
        note = '真伪探针通过：幽灵模型名被拒（HTTP ' + r.status + '），该渠道按真实模型名分发';
      } else {
        why = 'unclear';
        note = 'HTTP ' + r.status + ' 被拒' + (msg ? '（' + msg.slice(0, 60) + '）' : '') + '：未明确指向模型名错误';
      }
    } else if (r.status === 200) {
      why = 'echo';
      echoes = true;
      note = '警惕伪装：不存在的幽灵模型名也返回 200，说明该渠道忽略请求的 model 字段（仅做标签回显）';
    } else if (r.status === 0) {
      why = 'net';
      note = '探针未连通：' + (r.err || '网络错误');
    } else {
      /* 部分聚合反代（NewAPI/OneAPI）在找不到模型渠道时返回 HTTP 500/503 "无可用渠道" */
      if ((r.status === 500 || r.status === 503) && /无可用渠道|no available channel|model.*not|not.*model|channel.*not.*found/i.test(msg)) {
        why = 'rejected';
        echoes = false;
        note = '真伪探针通过：幽灵模型名无可用渠道（HTTP ' + r.status + '），该渠道按模型名路由';
      } else {
        why = 'unclear';
        note = 'HTTP ' + r.status + (msg ? '（' + msg.slice(0, 50) + '）' : '') + '，暂无法定性（可稍后重试）';
      }
    }
    if (echoes !== null) setChState({ echoes: echoes, note: note });
    PROBE_VERIFY_BUSY = false;
    render();
    return { ok: echoes !== null, echoes: echoes, status: r.status, note: note, msg: note,
      ghost: ghost, why: why, err: msg, raw: String((r && r.raw) || '').slice(0, 300) };
  })['catch'](function (eVerify) { PROBE_VERIFY_BUSY = false; throw eVerify; });
}

