function isGenerateUrl(u) {
  var s = String(u || '');
  if (!s) return false;
  /* 1) 桌面酒馆：请求先从服务端转发（/api/backends/chat-completions/generate） */
  if (/\/chat-completions\/generate\b/.test(s)) return true;
