      '<button type="button" data-ar6-card="decode" style="padding:3px 8px;border-radius:6px;border:1px solid rgba(148,163,184,.4);background:#162032;color:#cbd5e1;font-size:11px;cursor:pointer">解码/白名单</button>' +
    '</span></div>';
