    try { banner('🚨 试听：彩色计时器单音晶体红灯警报', 'warn'); } catch (eB1) {}
    return;
  } else if (act.indexOf('pet-sfx-') === 0) {
    var pk = act.slice(8);
    if (pk === 'tiga1996' || pk === 'glitter' || pk === 'dark' || pk === 'crisp') {
      p.sfxPreset = pk;
