function pvpDlgReadField(input) {
  try {
    var k = input.getAttribute('data-pvpk');
    if (!k) return;
    if (input.type === 'checkbox') cfg[k] = !!input.checked;
    else {
      var v = Number(input.value);
      if (!isFinite(v)) return;
      cfg[k] = v;
    }
    sanitizePvp(cfg);
    if (input.type !== 'checkbox') input.value = String(cfg[k]);
    saveCfg();
    render();
    pvpDlgSync();
  } catch (e) {}
}

