    for (var i = 0; i < ins.length; i++) {
      var k = ins[i].getAttribute('data-pvpk');
      if (!k) continue;
      if (ins[i].type === 'checkbox') ins[i].checked = !!cfg[k];
      else ins[i].value = String(cfg[k]);
