function liveSplit(s) {
  var out = { body: 0, think: 0 };
  try {
    var txt = String(s == null ? '' : s);
    var trimmed = txt.trim();
    if (!trimmed) return out;
    var parsedAny = false;
    if (trimmed.indexOf('data:') >= 0) {
      var lines = trimmed.split(/\r?\n/);
