    LIVE.last = snap;
    LIVE.on = false;
    liveStopTimer();
    livePublish(true);
    try { if (typeof paintLogWin === 'function' && LOGW && LOGW.open) paintLogWin(true); } catch (eW) {}
    return snap;
  } catch (e) { LIVE.on = false; liveStopTimer(); return null; }
}

