          }
        } catch (eBlur) {}
      });
    } catch (eBd) {}
  }
  bindDirect(r);
  if (VERIFY_T) { try { clearTimeout(VERIFY_T); } catch (eVT0) {} }
  VERIFY_T = setTimeout(function () { VERIFY_T = 0; verifyVisible(); }, 400);
  return true;
}

function uiTimersClear() {
