    var y = (cfg.logY == null) ? Math.max(8, Math.min(64, vh - h - 8)) : Number(cfg.logY);
    if (!isFinite(x)) x = Math.max(8, vw - w - 14);
    if (!isFinite(y)) y = 64;
    x = Math.min(Math.max(6, x), Math.max(6, vw - w - 6));
    y = Math.min(Math.max(6, y), Math.max(6, vh - Math.min(h, vh - 12) - 6));
